import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.DYPTBNgj.js";const h=JSON.parse('{"title":"Command-line reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md","lastUpdated":1788996123000}'),r={name:"reference/cli.md"};function n(i,e,c,s,l,m){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="command-line-reference" tabindex="-1">Command-line reference <a class="header-anchor" href="#command-line-reference" aria-label="Permalink to &quot;Command-line reference&quot;">​</a></h1><p>Run <code>boomerangz COMMAND --help</code> for the authoritative help installed with your version. Commands return exit status zero on success and one on failure; errors are written to standard error.</p><p>Commands that read configuration accept:</p><table tabindex="0"><thead><tr><th>Option</th><th>Default</th></tr></thead><tbody><tr><td><code>--config</code></td><td><code>/etc/boomerangz/config.toml</code></td></tr><tr><td><code>--config-dir</code></td><td><code>/etc/boomerangz/config.d</code></td></tr></tbody></table><h2 id="configuration-and-version" tabindex="-1">Configuration and version <a class="header-anchor" href="#configuration-and-version" aria-label="Permalink to &quot;Configuration and version&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>boomerangz config check</code></td><td>Validate the primary file, drop-ins, and merged configuration.</td></tr><tr><td><code>boomerangz config show</code></td><td>Print merged TOML with private-key fields redacted.</td></tr><tr><td><code>boomerangz config reload</code></td><td>Validate and atomically apply the running daemon configuration. Use <code>--socket PATH</code> to select a non-default current control socket. The JSON result lists the configuration generation, fields applied live, and fields requiring restart.</td></tr><tr><td><code>boomerangz version</code></td><td>Show build version, commit, and date.</td></tr><tr><td><code>boomerangz version --json</code></td><td>Emit version information as JSON.</td></tr></tbody></table><h2 id="daemon-and-operation" tabindex="-1">Daemon and operation <a class="header-anchor" href="#daemon-and-operation" aria-label="Permalink to &quot;Daemon and operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz daemon</code></td><td>Run management in the foreground.</td></tr><tr><td><code>boomerangz status</code></td><td><code>--credential NAME_OR_PATH</code>, <code>--watch</code>/<code>-w</code>, and <code>--interval DURATION</code> (default <code>2s</code>).</td></tr><tr><td><code>boomerangz trigger [DATASET...]</code></td><td>Empty selects every active root; <code>--credential NAME_OR_PATH</code> addresses a paired listener.</td></tr></tbody></table><p>Interactive status uses a readable terminal view. Redirected one-shot output is one JSON object; redirected watch output is newline-delimited JSON.</p><h2 id="dataset-lifecycle" tabindex="-1">Dataset lifecycle <a class="header-anchor" href="#dataset-lifecycle" aria-label="Permalink to &quot;Dataset lifecycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz dataset list</code></td><td>Print a readable inventory with each dataset&#39;s management status. Add <code>--json</code> for structured output.</td></tr><tr><td><code>boomerangz dataset inspect DATASET</code></td><td>Print readable effective policy, provenance, activation, coverage, warnings, and errors for one exact dataset. Add <code>--json</code> for structured output.</td></tr><tr><td><code>boomerangz dataset adopt DATASET</code></td><td>Preview adoption; <code>--apply</code> performs the revalidated plan.</td></tr><tr><td><code>boomerangz dataset reseed DATASET TARGET</code></td><td>Preview destruction and fresh seeding of one configured local destination root or named remote; <code>--apply</code> performs the revalidated plan.</td></tr><tr><td><code>boomerangz dataset clean [DATASET...]</code></td><td>Preview decommissioning. Use <code>--recursive</code>, <code>--all</code>, <code>--destroy-owned-snapshots</code>, and <code>--apply</code> as needed.</td></tr><tr><td><code>boomerangz identity recover</code></td><td>Preview recovery. <code>--owner UUID</code> resolves multiple candidates; <code>--apply</code> performs the revalidated plan.</td></tr></tbody></table><p><code>dataset clean --all</code> cannot be combined with dataset arguments. Named datasets are exact unless <code>--recursive</code> is supplied. Snapshot destruction is never implied by selecting a scope.</p><h2 id="pairing" tabindex="-1">Pairing <a class="header-anchor" href="#pairing" aria-label="Permalink to &quot;Pairing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Options and arguments</th></tr></thead><tbody><tr><td><code>boomerangz pairing create</code></td><td><code>--listener NAME</code>, repeatable <code>--scope VALUE</code>, <code>--expires-in DURATION</code>, and paired <code>--client-cert PATH</code>/<code>--client-key PATH</code>.</td></tr><tr><td><code>boomerangz pairing import NAME BUNDLE</code></td><td>Store a received bundle under a local credential name.</td></tr><tr><td><code>boomerangz pairing list</code></td><td>List credentials issued or imported by this installation.</td></tr><tr><td><code>boomerangz pairing revoke ID</code></td><td>Revoke one issued pairing.</td></tr></tbody></table><p>Allowed scope values are <code>status</code>, <code>trigger</code>, <code>replicate</code>, <code>prune</code>, and <code>admin</code>. The default is <code>status</code>. An expiry of <code>0s</code> means no expiry. <code>--client-cert</code> and <code>--client-key</code> must be supplied together.</p><h2 id="restricted-ssh-command" tabindex="-1">Restricted SSH command <a class="header-anchor" href="#restricted-ssh-command" aria-label="Permalink to &quot;Restricted SSH command&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boomerangz ssh-shell</span></span></code></pre></div><p>This command serves a restricted receiving endpoint over standard input and output. The packaged <code>/usr/lib/boomerangz/boomerangz-shell</code> login shell invokes it and ignores SSH command arguments. Destination roots are supplied through the replication API and checked against <code>ssh_shell.replication_roots</code>; there is no root command-line option. Administrators do not normally invoke this hidden command directly.</p>',18)])])}const u=t(r,[["render",n]]);export{h as __pageData,u as default};
